    case Tag::kMemory:
      return mojo::Equals(*(data_.memory), *(other.data_.memory));
    case Tag::kVolumeButton:
      return mojo::Equals(*(data_.volume_button), *(other.data_.volume_button));
    case Tag::kFan:
      return mojo::Equals(*(data_.fan), *(other.data_.fan));
